// Reading the action's inputs (see action.yml) into ActionInputs. Empty or invalid values fall back to DEFAULTS.
import type {
	CustomProviderConfig,
	ModelInputMode,
} from "./custom-provider.ts";
import { DEFAULTS } from "./defaults.ts";

export type InputReader = (name: string) => string;

export interface ActionInputs {
	triggerPhrase: string;
	allowedBots: string[];
	allowedUsers: string[];
	allowedAssociations: string[];
	provider: string;
	model: string;
	/** Seconds before the run is aborted. */
	timeout: number;
	githubToken: string | undefined;
	/** The provider's key, kept in memory for this run only. */
	apiKey: string | undefined;
	customProvider: CustomProviderConfig | undefined;
	promptTemplate: string | undefined;
	outputMode: "comment" | "output";
	prompt: string | undefined;
	prNumber: number | undefined;
	/** Seconds between checks for new comments while pi works. */
	pollInterval: number;
	/** pi extensions to load (npm specs or workspace paths) for the providers they register. */
	extensions: string[];
	/** Whether pi-durable extensions may load and run the repository's own configuration (`trust_project`). */
	trustProject: boolean;
	/** The agent directory for pi-durable extensions; a temp dir when unset. */
	agentDir: string | undefined;
}

const TRUE_VALUES = new Set(["true", "1", "yes", "y", "on"]);
const FALSE_VALUES = new Set(["false", "0", "no", "n", "off"]);
const MODEL_INPUT_MODES: ReadonlySet<string> = new Set<ModelInputMode>([
	"text",
	"image",
]);
const INTEGER_PATTERN = /^\d+$/u;
const EXTENSION_SEPARATOR = /[\n,]/u;
const COMPAT_INPUTS = {
	supportsDeveloperRole: "compat_supports_developer_role",
	supportsReasoningEffort: "compat_supports_reasoning_effort",
	forceAdaptiveThinking: "compat_force_adaptive_thinking",
} as const;

export function parseCsv(value: string): string[] {
	return value
		.split(",")
		.map((entry) => entry.trim())
		.filter(Boolean);
}

/** pi extension specs, newline- or comma-separated; blank lines and `#` comments are skipped. */
export function parseExtensionSpecs(value: string): string[] {
	return value
		.split(EXTENSION_SEPARATOR)
		.map((spec) => spec.trim())
		.filter((spec) => spec !== "" && !spec.startsWith("#"));
}

/** true/1/yes/y/on or false/0/no/n/off, in any case; undefined for anything else. */
export function parseBoolean(value: string): boolean | undefined {
	const normalized = value.trim().toLowerCase();
	if (TRUE_VALUES.has(normalized)) {
		return true;
	}
	return FALSE_VALUES.has(normalized) ? false : undefined;
}

export function parsePositiveInteger(value: string): number | undefined {
	const normalized = value.trim();
	const parsed = INTEGER_PATTERN.test(normalized)
		? Number.parseInt(normalized, 10)
		: 0;
	return parsed > 0 ? parsed : undefined;
}

function parseModelInputModes(value: string): ModelInputMode[] {
	const modes = parseCsv(value).filter((mode): mode is ModelInputMode =>
		MODEL_INPUT_MODES.has(mode),
	);
	return modes.length > 0 ? modes : [DEFAULTS.customModelInput];
}

function readCompat(readInput: InputReader): CustomProviderConfig["compat"] {
	const compat = Object.fromEntries(
		Object.entries(COMPAT_INPUTS).flatMap(([key, name]) => {
			const value = parseBoolean(readInput(name));
			return value === undefined ? [] : [[key, value]];
		}),
	);
	return Object.keys(compat).length > 0 ? compat : undefined;
}

/** The single custom provider/model from the flat provider_* and model_* inputs; undefined without a base URL. */
export function readCustomProviderConfig(
	readInput: InputReader,
): CustomProviderConfig | undefined {
	const baseUrl = readInput("provider_base_url").trim();
	if (!baseUrl) {
		return undefined;
	}
	const apiKey = readInput("provider_api_key").trim();
	const modelName = readInput("model_name").trim();
	const compat = readCompat(readInput);
	return {
		baseUrl,
		api: readInput("provider_api") || DEFAULTS.customProviderApi,
		...(apiKey ? { apiKey } : {}),
		authHeader:
			parseBoolean(readInput("provider_auth_header")) ??
			DEFAULTS.customProviderAuthHeader,
		...(modelName ? { modelName } : {}),
		reasoning:
			parseBoolean(readInput("model_reasoning")) ??
			DEFAULTS.customModelReasoning,
		input: parseModelInputModes(readInput("model_input")),
		contextWindow:
			parsePositiveInteger(readInput("model_context_window")) ??
			DEFAULTS.customModelContextWindow,
		maxTokens:
			parsePositiveInteger(readInput("model_max_tokens")) ??
			DEFAULTS.customModelMaxTokens,
		...(compat ? { compat } : {}),
	};
}

export function readActionInputs(
	readInput: InputReader,
	env: Record<string, string | undefined> = process.env,
): ActionInputs {
	return {
		triggerPhrase: readInput("trigger_phrase") || DEFAULTS.triggerPhrase,
		allowedBots: parseCsv(readInput("allowed_bots")),
		allowedUsers: parseCsv(readInput("allowed_users")),
		allowedAssociations: parseCsv(
			readInput("allowed_associations") ||
				DEFAULTS.allowedAssociations.join(","),
		),
		provider: readInput("provider") || DEFAULTS.provider,
		model: readInput("model") || DEFAULTS.model,
		timeout: parsePositiveInteger(readInput("timeout")) ?? DEFAULTS.timeout,
		githubToken: readInput("github_token") || env["GITHUB_TOKEN"],
		apiKey: readInput("api_key") || undefined,
		customProvider: readCustomProviderConfig(readInput),
		promptTemplate: readInput("prompt_template") || undefined,
		outputMode:
			readInput("output_mode") === "output" ? "output" : DEFAULTS.outputMode,
		prompt: readInput("prompt") || undefined,
		prNumber: parsePositiveInteger(readInput("pr_number")),
		pollInterval:
			parsePositiveInteger(readInput("poll_interval")) ?? DEFAULTS.pollInterval,
		extensions: parseExtensionSpecs(readInput("extensions")),
		trustProject:
			parseBoolean(readInput("trust_project")) ?? DEFAULTS.trustProject,
		agentDir: readInput("agent_dir").trim() || undefined,
	};
}
import type { GitHubUser } from "./types.ts";

/** Who may run pi, from the allowed_* inputs. */
export interface Allowlists {
	allowedBots: string[];
	allowedUsers: string[];
	allowedAssociations: string[];
}

const LEADING_AT_PATTERN = /^@/u;
const HTML_COMMENT_PATTERN = /<!--[\s\S]*?-->/gu;
const INVISIBLE_CHARACTERS_PATTERN = /\u200B|\u200C|\u200D|\uFEFF|\u00AD/gu;

const normalizeLogin = (login: string): string =>
	login.trim().replace(LEADING_AT_PATTERN, "").toLowerCase();

const normalizeAssociation = (association: string): string =>
	association.trim().toUpperCase();

function includesLogin(logins: string[], login: string): boolean {
	const normalized = normalizeLogin(login);
	return logins.some((allowed) => normalizeLogin(allowed) === normalized);
}

/**
 * Bots must be in allowed_bots. People must be in allowed_users when it is set, and otherwise have one of the
 * allowed_associations.
 */
export function validatePermissions(
	author: GitHubUser,
	association: string,
	allow: Allowlists,
): boolean {
	if (author.type === "Bot") {
		return includesLogin(allow.allowedBots, author.login);
	}
	if (allow.allowedUsers.length > 0) {
		return includesLogin(allow.allowedUsers, author.login);
	}
	return allow.allowedAssociations
		.map(normalizeAssociation)
		.includes(normalizeAssociation(association));
}

/** Drop HTML comments and invisible characters, which can hide instructions. */
export function sanitizeInput(text: string): string {
	return text
		.replaceAll(HTML_COMMENT_PATTERN, "")
		.replaceAll(INVISIBLE_CHARACTERS_PATTERN, "")
		.trim();
}
import type { Trigger } from "./triggers.ts";

export function hasTrigger(text: string, trigger: string): boolean {
	return text.toLowerCase().includes(trigger.toLowerCase());
}

/** Appended to every first prompt: the runner, and anything left uncommitted on it, is gone after the run. */
const RUNNER_REQUIREMENTS = `## Important: Artifact and Script Requirements

**CRITICAL:** After the GitHub Action finishes running, all files modified or created are lost, and the GitHub Action runner is destroyed. Therefore:

1. **All generated code and artifacts MUST be committed** - Any files you create, modify, or generate must be committed and pushed to the repository before the action completes. Nothing will persist otherwise.

2. **Any throw-away scripts generated MUST be run immediately** - If you create temporary scripts (like \`/tmp/create-issues.sh\` or similar), you must execute them during the same session. They will be lost when the runner terminates.

3. **Commit and push all work** - Always end your work by committing and pushing changes to ensure they persist beyond the GitHub Action execution.
`;

export function extractTask(comment: string, trigger: string): string {
	const idx = comment.toLowerCase().indexOf(trigger.toLowerCase());
	if (idx === -1) {
		return comment;
	}
	return comment.slice(idx + trigger.length).trim();
}

interface BasePIContext {
	type: "issue" | "pull_request" | "direct";
	title: string;
	task: string;
}

interface IssuePIContext extends BasePIContext {
	type: "issue";
	body: string;
	number: number;
	triggerComment: string;
}

interface PullRequestPIContext extends BasePIContext {
	type: "pull_request";
	body: string;
	number: number;
	triggerComment: string;
	diff?: string;
	reviewComments?: string;
}

interface DirectPIContext extends BasePIContext {
	type: "direct";
}

export type PIContext = IssuePIContext | PullRequestPIContext | DirectPIContext;

const PLACEHOLDER_PATTERN = /\{\{(\w+)\}\}/gu;

const TYPE_DISPLAY: Record<PIContext["type"], string> = {
	issue: "Issue",
	pull_request: "Pull Request",
	direct: "Direct Task",
};

export function renderTemplate(template: string, context: PIContext): string {
	const isDirect = context.type === "direct";
	const variables = new Map(
		Object.entries({
			type: context.type,
			type_display: TYPE_DISPLAY[context.type],
			number: isDirect ? "0" : context.number.toString(),
			title: context.title,
			body: isDirect ? "" : context.body,
			task: context.task,
			diff: context.type === "pull_request" ? (context.diff ?? "") : "",
			reviewComments:
				context.type === "pull_request" ? (context.reviewComments ?? "") : "",
			trigger_comment: isDirect ? context.task : context.triggerComment,
		}),
	);
	// One pass with a replacer: values go in literally ("$&" stays "$&"), and a placeholder inside a value (an
	// issue body that says {{diff}}) stays text instead of being expanded.
	return template.replaceAll(
		PLACEHOLDER_PATTERN,
		(placeholder, key: string) => variables.get(key) ?? placeholder,
	);
}

export function buildPrompt(
	context: PIContext,
	customTemplate?: string,
): string {
	if (customTemplate?.trim()) {
		return renderTemplate(customTemplate, context);
	}

	if (context.type === "direct") {
		return `# Direct pi Task

## Task
${context.task}

${RUNNER_REQUIREMENTS}`;
	}

	let prompt = `# GitHub ${TYPE_DISPLAY[context.type]} #${context.number}

## Title
${context.title}

## Description
${context.body}

${context.type === "pull_request" ? (context.reviewComments ?? "") : ""}
## Task
${context.task}

${RUNNER_REQUIREMENTS}`;

	if (context.type === "pull_request" && context.diff) {
		prompt += `\n## PR Diff\n\`\`\`diff\n${context.diff}\n\`\`\`\n`;
	}

	return prompt;
}

/** A later comment on an existing thread: the conversation already has the issue's context. */
export function formatFollowUp(
	trigger: Pick<Trigger, "author" | "source" | "task" | "url">,
): string {
	const verb =
		trigger.source === "review_comment" ? "commented on the diff" : "commented";
	const where = trigger.url ? ` (${trigger.url})` : "";
	return `**@${trigger.author.login}** ${verb}${where}:\n\n${trigger.task}`;
}

