type Env = Record<string, string | undefined>;

export interface Logger extends Log {
	error: (msg: string) => void;
	setFailed: (msg: string) => void;
	setOutput: (name: string, value: string) => void;
}

export interface ActionDependencies {
	inputs: ActionInputs;
	/** The webhook payload of the event that started the workflow. */
	payload: Record<string, unknown>;
	createClient: (token: string) => GitHubClient;
	log: Logger;
	cwd: string;
	/** Override model setup (tests use a faux provider). */
	createModels?: ((inputs: ActionInputs) => Promise<Models>) | undefined;
	/** Git remote holding the thread refs. Default "origin". */
	remote?: string;
	env?: Env;
	/** Appends Markdown to the job summary (notifications from pi-durable extensions). */
	summary?: (markdown: string) => Promise<void>;
}

/**
 * The `extensions` input and the model setup: the built-in and custom providers and those extensions register
 * (unless `createModels` overrides it), the pi-durable extensions for the thread, which get the GitHub UI when
 * the run posts to an issue or PR, and the variables the agent's tools get (see `toolEnv()`). pi-durable extensions
 * run in this process, so when there are any, those variables are set in its environment too (after npm ran).
 */
async function setUp(
	deps: ActionDependencies,
	gh: GitHubClient,
	issueNumber: number | undefined,
): Promise<{
	models: Models;
	extensions: Extension[];
	tools: Record<string, string>;
	ui: GitHubUi | undefined;
}> {
	const { inputs, log, cwd } = deps;
	const env = deps.env ?? process.env;
	const loaded = await loadExtensions({
		specs: inputs.extensions,
		cwd,
		log,
		env,
	});
	const models = deps.createModels
		? await deps.createModels(inputs)
		: await createActionModels(inputs, {
				providers: loaded.providers,
				env,
				log,
			});
	const tools = await toolEnv({ token: inputs.githubToken, cwd, env });
	if (Object.keys(tools).length > 0) {
		log.info(`The agent's tools get ${Object.keys(tools).join(", ")}`);
	}
	if (loaded.durable.length > 0) {
		Object.assign(env, tools);
	}
	const ui =
		inputs.outputMode === "comment" && issueNumber !== undefined
			? createGitHubUi({ gh, issueNumber, log, summary: deps.summary })
			: undefined;
	const extensions = await createDurableExtensions(loaded.durable, {
		cwd,
		agentDir: inputs.agentDir,
		trustProject: inputs.trustProject,
		ui,
		log,
		env,
	});
	return { models, extensions, tools, ui };
}

/** On cancellation (SIGINT, then SIGTERM), push what the thread has so far before the runner kills us. */
function pushOnSignals(thread: Thread, log: Log): () => void {
	const handler = (signal: NodeJS.Signals) => {
		log.warning(`Received ${signal}; saving the thread before exiting`);
		thread
			.push()
			.catch((error: unknown) => {
				log.warning(getErrorMessage(error));
			})
			.finally(() => {
				process.exitCode = 1;
				process.kill(process.pid, "SIGKILL");
			})
			.catch(() => undefined);
	};
	process.once("SIGINT", handler);
	process.once("SIGTERM", handler);
	return () => {
		process.off("SIGINT", handler);
		process.off("SIGTERM", handler);
	};
}

/** The context of the first message of a thread, for the trigger that starts it. */
function contextFor(piContext: PIContext, trigger: Trigger): PIContext {
	return piContext.type === "direct"
		? piContext
		: { ...piContext, task: trigger.task, triggerComment: trigger.text };
}

/** A run from workflow_dispatch or a direct prompt: one request, keyed by the workflow run. */
function oneOffTrigger(piContext: PIContext, env: Env): Trigger {
	const runId = env["GITHUB_RUN_ID"] ?? String(Date.now());
	const attempt = env["GITHUB_RUN_ATTEMPT"] ?? "1";
	return {
		key: `run-${runId}-${attempt}`,
		source: "body",
		issueNumber: piContext.type === "direct" ? 0 : piContext.number,
		author: { login: env["GITHUB_ACTOR"] ?? "workflow", type: "User" },
		text: piContext.task,
		task: piContext.task,
		createdAt: new Date().toISOString(),
	};
}

/** What the run starts with: every unanswered trigger on the thread in comment mode, else one request. */
async function initialTriggers(
	deps: ActionDependencies,
	gh: GitHubClient,
	piContext: PIContext,
	triggerInfo: TriggerInfo | undefined,
	since: Date | undefined,
	answer: Trigger | undefined,
): Promise<Trigger[]> {
	const { inputs } = deps;
	if (!triggerInfo) {
		return [oneOffTrigger(piContext, deps.env ?? process.env)];
	}
	const current = answer ?? triggerFromInfo(triggerInfo, inputs.triggerPhrase);
	return inputs.outputMode === "comment"
		? collectTriggers(gh, triggerInfo, inputs, since, current)
		: [current];
}

/** Close the thread, pushing it; a failure to save is a warning, not a failed run. */
async function closeThread(thread: Thread, log: Log): Promise<void> {
	try {
		await thread.close();
	} catch (error) {
		log.warning(
			error instanceof GitSyncConflictError
				? `${thread.ref} moved on the remote while this run worked; its history was not pushed. ${getErrorMessage(error)}`
				: `Could not save the thread: ${getErrorMessage(error)}`,
		);
	}
}

export async function run(deps: ActionDependencies): Promise<void> {
	const resolved = await getRunContext(deps);
	if (!resolved) {
		return;
	}
	const { piContext, ghClient: gh, triggerInfo } = resolved;
	const { inputs, log } = deps;
	log.info(`Running pi agent for: ${piContext.task}`);
	const issueNumber =
		piContext.type === "direct" ? undefined : piContext.number;
	// In comment mode, a trigger makes the run a conversation on its issue or PR (reactions, new comments join).
	const interactive = inputs.outputMode === "comment" ? triggerInfo : undefined;

	/** Set the outputs, or react on `target` and post the result unless it was posted before. Returns where it went. */
	const report = async (
		result: ThreadResult,
		target: ReactionTarget | undefined,
		ref?: string,
		alreadyPosted = false,
	): Promise<string | undefined> => {
		if (!result.success) {
			log.error(`pi execution failed: ${result.error}`);
		}
		if (inputs.outputMode === "output") {
			log.setOutput("success", String(result.success));
			log.setOutput(
				"response",
				result.success ? result.response : result.error,
			);
			return "output";
		}
		if (target) {
			await gh.addReaction(target, result.success ? "rocket" : "confused");
		}
		if (alreadyPosted || issueNumber === undefined) {
			return undefined;
		}
		const body = result.success
			? formatSuccessComment(result.response, ref)
			: formatErrorComment(result.error, ref);
		return (await gh.createComment(issueNumber, body)).url;
	};

	if (interactive) {
		await gh.addReaction(interactive, "eyes");
	}
	let thread: Thread | undefined;
	let stopSignals: (() => void) | undefined;
	try {
		const { models, extensions, tools, ui } = await setUp(
			deps,
			gh,
			issueNumber,
		);
		const opened = await Thread.open({
			cwd: deps.cwd,
			issueNumber,
			models,
			model: findModel(models, inputs.provider, inputs.model),
			log,
			remote: deps.remote,
			extensions,
			toolEnv: tools,
		});
		thread = opened;
		stopSignals = pushOnSignals(opened, log);
		log.info(
			opened.ref
				? `Thread ${opened.ref}: ${opened.isNew ? "new" : `since ${opened.startedAt?.toISOString()}`}`
				: "One-off conversation (not stored)",
		);
		// New comments: on a new thread, from the time of the trigger; on an existing one, since it began.
		const since =
			opened.startedAt ??
			new Date(
				Date.parse(interactive?.createdAt ?? new Date().toISOString()) - 1000,
			);
		const conversation = new ThreadConversation({
			thread: opened,
			log,
			timeoutSeconds: inputs.timeout,
			pollIntervalMs: inputs.pollInterval * 1000,
			message: async (trigger, first) => {
				if (trigger.answer) {
					return trigger.text;
				}
				return first
					? buildPrompt(contextFor(piContext, trigger), inputs.promptTemplate)
					: formatFollowUp(trigger);
			},
			deliver: async (trigger, result, alreadyPosted) =>
				report(
					result,
					interactive ? trigger : undefined,
					opened.ref,
					alreadyPosted,
				),
			...(interactive
				? { poll: async () => collectTriggers(gh, interactive, inputs, since) }
				: {}),
			...(ui ? { asked: () => ui.asked } : {}),
		});
		await conversation.run(
			await initialTriggers(
				deps,
				gh,
				piContext,
				triggerInfo,
				opened.startedAt,
				resolved.answer,
			),
		);
	} catch (error) {
		await report(
			{ success: false, error: getErrorMessage(error) },
			interactive,
		);
	} finally {
		stopSignals?.();
		if (thread) {
			await closeThread(thread, log);
		}
	}
}
// What a run works on: the pull request of pr_number, a direct prompt, or the issue/PR/comment that triggered it.
import { answerFromEvent, questionEventKind } from "./answers.ts";
import { extractTask, hasTrigger, type PIContext } from "./context.ts";
import { formatReviewComments } from "./formatting.ts";
import { isQuestionComment } from "./github-ui.ts";
import { extractTriggerInfo, type GitHubClient } from "./github.ts";
import type { ActionDependencies } from "./run.ts";
import { sanitizeInput, validatePermissions } from "./security.ts";
import type { Trigger } from "./triggers.ts";
import type { Log, TriggerInfo } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

export interface ResolvedRunContext {
	piContext: PIContext;
	ghClient: GitHubClient;
	triggerInfo?: TriggerInfo;
	/** The answer to a question that started this run (a ticked box or an `/answer` reply), as its trigger. */
	answer?: Trigger;
}

function createClient(deps: ActionDependencies): GitHubClient | null {
	const { inputs, createClient: create, log } = deps;
	if (!inputs.githubToken) {
		log.setFailed("github_token is required");
		return null;
	}
	return create(inputs.githubToken);
}

/** A pull request's diff and existing review comments (left out, with a warning, if they can't be listed). */
async function pullRequestDetails(
	gh: GitHubClient,
	pullNumber: number,
	log: Log,
): Promise<{ diff: string; reviewComments?: string }> {
	const diff = await gh.getPullRequestDiff(pullNumber);
	try {
		const reviewComments = formatReviewComments(
			await gh.listReviewComments(pullNumber),
		);
		return reviewComments ? { diff, reviewComments } : { diff };
	} catch (error) {
		log.warning(
			`Failed to fetch PR review comments: ${getErrorMessage(error)}`,
		);
		return { diff };
	}
}

/** The trigger of the event, if it mentions the trigger phrase and its author may run pi. */
function permittedTrigger(deps: ActionDependencies): TriggerInfo | null {
	const { inputs, payload, log } = deps;
	const info = extractTriggerInfo(payload);
	if (payload["action"] === "edited") {
		log.info("An edited comment that is not an answer to a question; skipping");
		return null;
	}
	if (!info) {
		log.info("No issue or pull_request in payload, skipping");
		return null;
	}
	if (!hasTrigger(info.triggerText, inputs.triggerPhrase)) {
		log.info(`No trigger phrase "${inputs.triggerPhrase}" found, skipping`);
		return null;
	}
	if (info.source === "comment" && isQuestionComment(info.triggerText)) {
		log.info(
			"An answer to a question from an extension, not a request; skipping",
		);
		return null;
	}
	if (!validatePermissions(info.author, info.authorAssociation, inputs)) {
		log.warning(
			`User ${info.author.login} (${info.authorAssociation}) does not have permission`,
		);
		return null;
	}
	return info;
}

export async function getRunContext(
	deps: ActionDependencies,
): Promise<ResolvedRunContext | null> {
	const { inputs, log } = deps;
	if (inputs.prNumber !== undefined) {
		const ghClient = createClient(deps);
		if (!ghClient) {
			return null;
		}
		const pr = await ghClient.getPullRequest(inputs.prNumber);
		const task = inputs.prompt?.trim() || "Please review this pull request";
		return {
			ghClient,
			piContext: {
				type: "pull_request",
				title: pr.title,
				body: pr.body,
				number: pr.number,
				triggerComment: task,
				task,
				...(await pullRequestDetails(ghClient, pr.number, log)),
			},
		};
	}

	if (inputs.prompt) {
		if (inputs.outputMode !== "output") {
			log.setFailed(
				"prompt requires output_mode: output when no PR number is set",
			);
			return null;
		}
		const ghClient = createClient(deps);
		const piContext: PIContext = {
			type: "direct",
			title: "Direct prompt",
			task: inputs.prompt,
		};
		return ghClient ? { ghClient, piContext } : null;
	}

	if (questionEventKind(deps.payload) !== undefined) {
		return answerContext(deps);
	}
	const triggerInfo = permittedTrigger(deps);
	const ghClient = triggerInfo ? createClient(deps) : null;
	if (!(triggerInfo && ghClient)) {
		return null;
	}
	const triggerComment = sanitizeInput(triggerInfo.triggerText);
	return {
		ghClient,
		triggerInfo,
		piContext: await subjectContext(
			ghClient,
			triggerInfo,
			triggerComment,
			extractTask(triggerComment, inputs.triggerPhrase),
			log,
		),
	};
}

/** The issue or PR as the context of a run, its trigger being `triggerComment`. */
async function subjectContext(
	ghClient: GitHubClient,
	triggerInfo: TriggerInfo,
	triggerComment: string,
	task: string,
	log: Log,
): Promise<PIContext> {
	const subject = {
		title: triggerInfo.issueTitle,
		body: triggerInfo.issueBody,
		number: triggerInfo.issueNumber,
		triggerComment,
		task,
	};
	return triggerInfo.isPullRequest
		? {
				type: "pull_request",
				...subject,
				...(await pullRequestDetails(ghClient, subject.number, log)),
			}
		: { type: "issue", ...subject };
}

/** A run started by an answer to a question: it continues the thread with the answer. */
async function answerContext(
	deps: ActionDependencies,
): Promise<ResolvedRunContext | null> {
	const { inputs, payload, log } = deps;
	const ghClient = createClient(deps);
	if (!ghClient) {
		return null;
	}
	const event = await answerFromEvent(payload, {
		gh: ghClient,
		allow: inputs,
		log,
	});
	if (!event) {
		return null;
	}
	const { info, trigger } = event;
	return {
		ghClient,
		triggerInfo: info,
		answer: trigger,
		piContext: await subjectContext(
			ghClient,
			info,
			trigger.text,
			trigger.task,
			log,
		),
	};
}
// The environment the agent's tools get on a runner: a token for gh, and a git identity for `git commit`.
import { execFile } from "node:child_process";

type Env = Readonly<Record<string, string | undefined>>;

/** The identity GitHub Actions commits as (the `github-actions[bot]` user). */
export const ACTIONS_BOT = {
	name: "github-actions[bot]",
	email: "41898282+github-actions[bot]@users.noreply.github.com",
} as const;

/** Reads one git config key in `cwd`; resolves undefined when it is unset. */
type GitConfigReader = (
	cwd: string,
	key: string,
	env: Env,
) => Promise<string | undefined>;

const readGitConfig: GitConfigReader = async (cwd, key, env) =>
	new Promise((resolve) => {
		execFile("git", ["config", "--get", key], { cwd, env }, (error, stdout) => {
			resolve(error ? undefined : stdout.trim() || undefined);
		});
	});

export interface ToolEnvOptions {
	/** The `github_token` input. */
	token: string | undefined;
	/** The workspace, whose git config may already have an identity. */
	cwd: string;
	/** The action's environment. */
	env: Env;
	/** Default: `git config --get` in `cwd` with `env`. */
	readConfig?: GitConfigReader | undefined;
}

const set = (value: string | undefined): boolean =>
	value !== undefined && value !== "";

/**
 * What the agent's tools need and the runner lacks, without overriding anything the workflow set: `GH_TOKEN` (the
 * `github_token` input) unless `GH_TOKEN` or `GITHUB_TOKEN` is set, and `GIT_AUTHOR_*`/`GIT_COMMITTER_*` as
 * `github-actions[bot]`, each unless it is set or git has `user.name` (or `user.email`) configured.
 */
export async function toolEnv(
	options: ToolEnvOptions,
): Promise<Record<string, string>> {
	const { token, cwd, env } = options;
	const readConfig = options.readConfig ?? readGitConfig;
	const vars: Record<string, string> = {};
	if (set(token) && !set(env["GH_TOKEN"]) && !set(env["GITHUB_TOKEN"])) {
		vars["GH_TOKEN"] = token ?? "";
	}
	const [name, email] = await Promise.all([
		readConfig(cwd, "user.name", env),
		readConfig(cwd, "user.email", env),
	]);
	for (const role of ["AUTHOR", "COMMITTER"]) {
		if (name === undefined && !set(env[`GIT_${role}_NAME`])) {
			vars[`GIT_${role}_NAME`] = ACTIONS_BOT.name;
		}
		if (email === undefined && !set(env[`GIT_${role}_EMAIL`])) {
			vars[`GIT_${role}_EMAIL`] = ACTIONS_BOT.email;
		}
	}
	return vars;
}
// The comments pi-action posts, and existing PR review comments as prompt context.
import type { GitHubComment } from "./types.ts";

/** `ref`, the thread's ref (e.g. refs/pi/threads/42), adds a footer saying where the thread is stored. */
function footer(ref: string | undefined): string {
	return ref
		? `\n\n---\n🧵 Thread state: \`${ref}\` (\`git fetch origin ${ref}\`)`
		: "";
}

export function formatSuccessComment(response: string, ref?: string): string {
	return `### 🤖 pi Response\n\n${response}${footer(ref)}`;
}

export function formatErrorComment(error: string, ref?: string): string {
	return `### ❌ pi Error\n\nFailed to process request: ${error}${footer(ref)}`;
}

export function formatReviewComments(comments: GitHubComment[]): string {
	if (comments.length === 0) {
		return "";
	}
	const sections: string[] = [
		"## Existing PR Review Comments",
		"",
		"These comments were already present on the PR. Do not re-fetch them unless you need newer comments.",
		"",
	];
	for (const comment of comments) {
		const author = comment.user?.login ?? "ghost";
		const [date = ""] = new Date(comment.created_at).toISOString().split("T");
		const location =
			comment.path && typeof comment.line === "number"
				? ` (${comment.path}:${comment.line})`
				: "";
		sections.push(
			`**${author}** on ${date}${location}:`,
			comment.body ?? "",
			"",
		);
	}
	return sections.join("\n");
}
/** The message of a thrown value, whatever was thrown. */
export function getErrorMessage(error: unknown): string {
	if (error instanceof Error) {
		return error.message;
	}
	if (typeof error === "string") {
		return error;
	}
	if (typeof error === "object" && error !== null && "message" in error) {
		return String(error.message);
	}
	return "Unknown error";
}

export function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** A property of an object from outside (JSON, an extension); undefined for anything else. */
export function field(value: unknown, key: string): unknown {
	return isRecord(value) ? value[key] : undefined;
}
